import{_ as t,o as a,c as s,a0 as i}from"./chunks/framework.CBux2OW7.js";const g=JSON.parse('{"title":"NewsAgent & NewsService","description":"","frontmatter":{},"headers":[],"relativePath":"backend/services/news-agent.md","filePath":"backend/services/news-agent.md"}'),o={name:"backend/services/news-agent.md"};function r(c,e,n,d,l,h){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="newsagent-newsservice" tabindex="-1">NewsAgent &amp; NewsService <a class="header-anchor" href="#newsagent-newsservice" aria-label="Permalink to &quot;NewsAgent &amp; NewsService&quot;">​</a></h1><p>These two services handle the autonomous, scheduled operations that drive the platform.</p><h2 id="newsservice-php" tabindex="-1"><code>NewsService.php</code> <a class="header-anchor" href="#newsservice-php" aria-label="Permalink to &quot;`NewsService.php`&quot;">​</a></h2><p>Responsible for data ingestion.</p><ul><li>Polls a predefined array of RSS URLs.</li><li>Uses SimpleXML to parse feeds.</li><li>Sanitizes input and deduplicates based on title strings and source URLs.</li><li>Populates the <code>scouted_articles</code> table.</li></ul><h2 id="newsagent-php" tabindex="-1"><code>NewsAgent.php</code> <a class="header-anchor" href="#newsagent-php" aria-label="Permalink to &quot;`NewsAgent.php`&quot;">​</a></h2><p>The orchestration engine that ties <code>NewsService</code> and <code>GeminiService</code> together. It acts as the autonomous &quot;Editor-in-Chief&quot;.</p><p><strong>Execution Flow (triggered via CRON <code>php artisan news:generate-daily</code>):</strong></p><ol><li>Calls <code>NewsService</code> to fetch fresh signals.</li><li>Selects the top 5 unprocessed <code>ScoutedArticle</code> rows.</li><li>Passes them to <code>GeminiService-&gt;generateIdeas()</code>.</li><li>Selects the best idea (heuristically or via AI scoring).</li><li>Calls <code>GeminiService-&gt;generateDraft()</code>.</li><li>Saves the new <code>Article</code> to the database.</li><li>Dispatches a job to <code>FactCheckService</code> to verify the new article asynchronously.</li><li>Marks the <code>ScoutedArticle</code> rows as <code>is_processed = true</code>.</li></ol><h2 id="observability" tabindex="-1">Observability <a class="header-anchor" href="#observability" aria-label="Permalink to &quot;Observability&quot;">​</a></h2><p><code>NewsAgent</code> logs its state transitions heavily. It uses <code>Log::info()</code> and <code>Log::error()</code> at every step so the <code>/dashboard</code> UI can parse the logs and visualize the agent&#39;s progress in real-time.</p>',11)])])}const u=t(o,[["render",r]]);export{g as __pageData,u as default};
